const identityWait = 35 * time.Millisecond

func identityDone(t *testing.T, cb *TwoStepCircuitBreaker) func(bool) {
 t.Helper()
 done, err := cb.Allow()
 if err != nil || done == nil { t.Fatalf("Allow: callback present=%v err=%v", done != nil, err) }
 return done
}

func identityRejected(t *testing.T, cb *TwoStepCircuitBreaker, want error) {
 t.Helper()
 done, err := cb.Allow()
 if done != nil || err != want { t.Fatalf("Allow: callback present=%v err=%v want %v", done != nil, err, want) }
}

func identityCounts(t *testing.T, cb interface{Counts() Counts}, want Counts) {
 t.Helper()
 if got := cb.Counts(); got != want { t.Fatalf("counts %+v want %+v", got, want) }
}

func identityState(t *testing.T, cb interface{State() State}, want State) {
 t.Helper()
 if got := cb.State(); got != want { t.Fatalf("state %v want %v", got, want) }
}

func identityPanic(t *testing.T, fn func(), want interface{}) {
 t.Helper()
 var got interface{}
 func() { defer func(){ got = recover() }(); fn() }()
 if got != want { t.Fatalf("panic %v want %v", got, want) }
}

