func TestIdentityClassifierAcrossTransition(t *testing.T) {
 for _, order := range []string{"fresh","request blocked","classifier blocked"} {
  for _, success := range []bool{true,false} {
   label := "/failure"; if success { label = "/success" }
   t.Run(order+label,func(t *testing.T){
    original, trip := errors.New("original"), errors.New("trip")
    started, release := make(chan struct{}), make(chan struct{})
    calls, classified := 0,0
    cb := NewCircuitBreaker(Settings{Timeout:time.Hour, ReadyToTrip:func(c Counts)bool{calls++;return order!="fresh"},
     IsSuccessful:func(err error)bool{
      if err==trip {return false}
      if err!=original {panic(err)}
      classified++
      if order=="classifier blocked" {close(started); <-release}
      return success
     }})
    request := func()(interface{},error){
     if order=="request blocked" {close(started); <-release}
     return "result",original
    }
    type pair struct{ v interface{}; e error }
    var result pair
    if order=="fresh" {result.v,result.e=cb.Execute(request)} else {
     finished := make(chan pair,1)
     go func(){v,e:=cb.Execute(request); finished<-pair{v,e}}()
     <-started
     cb.Execute(func()(interface{},error){return nil,trip})
     close(release)
     result=<-finished
    }
    if result.v!="result" || result.e!=original || classified!=1 {t.Fatal(result,classified)}
    if order!="fresh" {
     identityState(t,cb,StateOpen); identityCounts(t,cb,Counts{})
     if calls!=1 {t.Fatal(calls)}
    } else if success {identityCounts(t,cb,Counts{Requests:1, TotalSuccesses:1, ConsecutiveSuccesses:1}); if calls!=0{t.Fatal(calls)}
    } else {identityCounts(t,cb,Counts{Requests:1, TotalFailures:1, ConsecutiveFailures:1}); if calls!=1{t.Fatal(calls)}}
   })
  }
 }
}

func identityPanicBoundary(t *testing.T, classifier bool) {
 t.Helper()
 for _, order := range []string{"fresh","stale"} {
  t.Run(order,func(t *testing.T){
   original, trip := errors.New("original"), errors.New("trip")
   started, release := make(chan struct{}), make(chan struct{})
   calls, classified := 0,0
   block := func(){if order=="stale" {close(started);<-release}}
   cb:=NewCircuitBreaker(Settings{Timeout:time.Hour,
    ReadyToTrip:func(Counts)bool{calls++;return order=="stale"},
    IsSuccessful:func(err error)bool{if err==trip{return false};classified++;block();panic(original)}})
   execute:=func(){cb.Execute(func()(interface{},error){if classifier{return "value",nil};block();panic(original)})}
   if order=="fresh" {identityPanic(t,execute,original);identityCounts(t,cb,Counts{Requests:1,TotalFailures:1,ConsecutiveFailures:1})} else {
    recovered:=make(chan interface{},1)
    go func(){defer func(){recovered<-recover()}();execute()}()
    <-started
    cb.Execute(func()(interface{},error){return nil,trip})
    close(release)
    if got:=<-recovered;got!=original{t.Fatal(got)}
    identityState(t,cb,StateOpen)
    identityCounts(t,cb,Counts{})
   }
   if calls!=1 || (classifier && classified!=1) || (!classifier && classified!=0) {t.Fatal(calls,classified)}
  })
 }
}

